/**
 * Todo 应用数据层 —— 状态与持久化的唯一权威。
 *
 * 依赖方向：app.js → store.js；store.js 只依赖注入的 storage 适配器
 * （getItem / setItem / removeItem），不触碰 DOM，不使用全局 localStorage。
 * 约束来源：docs/contracts/todo-spa-app-v1.md（v1 冻结）。
 */

export const STORAGE_KEY = 'todo.spa.state';
export const CORRUPT_KEY_PREFIX = 'todo.spa.state.corrupt.';
// storage 适配器无「枚举键」能力，故用一份索引键记录最近一次损坏备份，
// 以便下次损坏时删除旧备份，使「仅保留最近 1 份」在任意适配器上成立。
// 索引键刻意不落在 CORRUPT_KEY_PREFIX 前缀内，避免与备份键混淆。
export const CORRUPT_INDEX_KEY = 'todo.spa.state.corrupt-index';
export const SCHEMA_VERSION = 1;
// 按码点计数（Array.from），避免代理对被截断。
export const MAX_TITLE_LEN = 200;
export const CAPACITY_LIMIT = 2000;

export const ERROR_CODES = Object.freeze({
  TITLE_EMPTY: 'TITLE_EMPTY',
  TITLE_TOO_LONG: 'TITLE_TOO_LONG',
  STORAGE_UNAVAILABLE: 'STORAGE_UNAVAILABLE',
  STORAGE_CORRUPT: 'STORAGE_CORRUPT',
  SCHEMA_TOO_NEW: 'SCHEMA_TOO_NEW',
  TODO_NOT_FOUND: 'TODO_NOT_FOUND',
  CAPACITY_EXCEEDED: 'CAPACITY_EXCEEDED',
});

/* ------------------------------------------------------------------ *
 * v1 schema
 *   { schemaVersion: 1, todos: [{ id, title, done, createdAt }] }
 * 读取时保留未知字段，写出时投影到当前版本（serialize）。
 * ------------------------------------------------------------------ */

// 逐级迁移表：键 = 源版本，值 = 迁到「下一版本」的纯函数。
// v2 分支点：新增字段时在此实现 v1→v2；删/改字段须同时提升 SCHEMA_VERSION
// 并在 README 记录弃用说明。
const MIGRATIONS = Object.freeze({
  // 1: (raw) => ({ ...raw, schemaVersion: 2, todos: raw.todos.map((t) => ({ ...t, dueAt: null })) }),
});

function fail(code, detail) {
  return { ok: false, code, detail };
}

function messageOf(err) {
  if (err && typeof err.message === 'string') return err.message;
  return String(err);
}

export function createState(todos = []) {
  return { schemaVersion: SCHEMA_VERSION, todos: Array.isArray(todos) ? [...todos] : [] };
}

/* ------------------------------ 校验 ------------------------------ */

// 返回 { ok: true, title } 或 { ok: false, code, detail }；非字符串一律视为空标题。
export function validateTitle(raw) {
  if (typeof raw !== 'string') {
    return fail(ERROR_CODES.TITLE_EMPTY, {
      reason: 'not-a-string',
      receivedType: raw === null ? 'null' : typeof raw,
    });
  }
  const title = raw.trim();
  if (title === '') return fail(ERROR_CODES.TITLE_EMPTY, { reason: 'blank' });
  const length = Array.from(title).length;
  if (length > MAX_TITLE_LEN) {
    return fail(ERROR_CODES.TITLE_TOO_LONG, { limit: MAX_TITLE_LEN, actual: length });
  }
  return { ok: true, title };
}

/* --------------------------- id 与时间戳 --------------------------- */

// crypto.randomUUID() 优先；不可用时回退 t<timestamp>-<random>。
export function createId() {
  const cryptoObj = globalThis.crypto;
  if (cryptoObj && typeof cryptoObj.randomUUID === 'function') {
    try {
      const id = cryptoObj.randomUUID();
      if (typeof id === 'string' && id !== '') return id;
    } catch {
      // 回退到时间戳 + 随机串
    }
  }
  return `t${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

// id 唯一性由 store 负责：生成器撞库时重试，仍冲突则追加序号，绝不返回重复 id。
function uniqueId(todos, makeId) {
  const used = new Set(todos.map((todo) => todo.id));
  for (let attempt = 0; attempt < 10; attempt += 1) {
    const candidate = String(makeId());
    if (candidate !== '' && !used.has(candidate)) return candidate;
  }
  const base = String(makeId());
  let suffix = 1;
  let candidate = `${base}-${suffix}`;
  while (used.has(candidate)) {
    suffix += 1;
    candidate = `${base}-${suffix}`;
  }
  return candidate;
}

function toIso(value) {
  if (value instanceof Date) return value.toISOString();
  if (typeof value === 'string' && !Number.isNaN(Date.parse(value))) return value;
  // 注入的 now() 非法时退回真实时钟（默认实现恒合法）。
  return new Date().toISOString();
}

// 列表按 createdAt 升序展示；时钟回拨时把新条目的 createdAt 钳到末条目，保证追加顺序即展示顺序。
function nextCreatedAt(todos, candidate) {
  const last = todos.length > 0 ? todos[todos.length - 1] : null;
  if (last && typeof last.createdAt === 'string' && last.createdAt > candidate) return last.createdAt;
  return candidate;
}

/* --------------------------- 变更（纯函数） --------------------------- */

function assertStateShape(state) {
  if (!state || typeof state !== 'object' || !Array.isArray(state.todos)) {
    return fail(ERROR_CODES.STORAGE_CORRUPT, { reason: 'state-invalid' });
  }
  return null;
}

export function addTodo(state, rawTitle, options = {}) {
  const invalid = assertStateShape(state);
  if (invalid) return invalid;

  const validation = validateTitle(rawTitle);
  if (!validation.ok) return validation;

  if (state.todos.length >= CAPACITY_LIMIT) {
    return fail(ERROR_CODES.CAPACITY_EXCEEDED, { limit: CAPACITY_LIMIT, count: state.todos.length });
  }

  const makeId = typeof options.makeId === 'function' ? options.makeId : createId;
  const now = typeof options.now === 'function' ? options.now : () => new Date().toISOString();

  const todo = {
    id: uniqueId(state.todos, makeId),
    title: validation.title,
    done: false,
    createdAt: nextCreatedAt(state.todos, toIso(now())),
  };
  return {
    ok: true,
    state: { ...state, schemaVersion: SCHEMA_VERSION, todos: [...state.todos, todo] },
  };
}

export function toggleTodo(state, id) {
  const invalid = assertStateShape(state);
  if (invalid) return invalid;

  const index = state.todos.findIndex((todo) => todo.id === id);
  if (index === -1) return fail(ERROR_CODES.TODO_NOT_FOUND, { id });

  const todos = state.todos.map((todo, i) => (i === index ? { ...todo, done: !todo.done } : todo));
  return { ok: true, state: { ...state, schemaVersion: SCHEMA_VERSION, todos } };
}

export function removeTodo(state, id) {
  const invalid = assertStateShape(state);
  if (invalid) return invalid;

  const index = state.todos.findIndex((todo) => todo.id === id);
  if (index === -1) return fail(ERROR_CODES.TODO_NOT_FOUND, { id });

  const todos = state.todos.filter((todo, i) => i !== index);
  return { ok: true, state: { ...state, schemaVersion: SCHEMA_VERSION, todos } };
}

/* --------------------------- 序列化与迁移 --------------------------- */

// 写出时投影到当前版本：只保留当前 schema 的字段。
export function serialize(state) {
  const todos = state && Array.isArray(state.todos) ? state.todos : [];
  const projected = todos.map((todo) => ({
    id: todo.id,
    title: todo.title,
    done: todo.done,
    createdAt: todo.createdAt,
  }));
  return JSON.stringify({ schemaVersion: SCHEMA_VERSION, todos: projected });
}

function corruptResult(reason, extra = {}) {
  return {
    ok: false,
    code: ERROR_CODES.STORAGE_CORRUPT,
    detail: { reason, ...extra },
    state: createState(),
    readOnly: false,
    fromVersion: null,
    migrated: false,
  };
}

function validateStoredTodo(item, index) {
  if (!item || typeof item !== 'object' || Array.isArray(item)) {
    return { ok: false, detail: { reason: 'todo-not-object', index } };
  }
  if (typeof item.id !== 'string' || item.id.trim() === '') {
    return { ok: false, detail: { reason: 'todo-id-invalid', index } };
  }
  if (typeof item.title !== 'string') {
    return { ok: false, detail: { reason: 'todo-title-invalid', index, code: ERROR_CODES.TITLE_EMPTY } };
  }
  // 只校验不改造：外部写入的合法标题按原样保留（前向兼容），不静默改写用户数据。
  const titleCheck = validateTitle(item.title);
  if (!titleCheck.ok) {
    return { ok: false, detail: { reason: 'todo-title-invalid', index, code: titleCheck.code } };
  }
  if (typeof item.done !== 'boolean') {
    return { ok: false, detail: { reason: 'todo-done-invalid', index } };
  }
  if (typeof item.createdAt !== 'string' || Number.isNaN(Date.parse(item.createdAt))) {
    return { ok: false, detail: { reason: 'todo-createdat-invalid', index } };
  }
  return { ok: true, todo: item };
}

function validateStateStructure(raw) {
  if (!Array.isArray(raw.todos)) {
    return { ok: false, detail: { reason: 'todos-not-array' } };
  }
  const seen = new Set();
  for (let index = 0; index < raw.todos.length; index += 1) {
    const checked = validateStoredTodo(raw.todos[index], index);
    if (!checked.ok) return checked;
    if (seen.has(checked.todo.id)) {
      return { ok: false, detail: { reason: 'todo-id-duplicate', index, id: checked.todo.id } };
    }
    seen.add(checked.todo.id);
  }
  if (raw.todos.length > CAPACITY_LIMIT) {
    return { ok: false, detail: { reason: 'capacity-exceeded', count: raw.todos.length, limit: CAPACITY_LIMIT } };
  }
  // 排序契约：按 createdAt 升序（sort 稳定，同值保持原有顺序）。
  const todos = [...raw.todos].sort((a, b) => (a.createdAt < b.createdAt ? -1 : a.createdAt > b.createdAt ? 1 : 0));
  return { ok: true, state: { ...raw, schemaVersion: SCHEMA_VERSION, todos } };
}

// migrate 接收「已解析的对象」，逐级升级到 SCHEMA_VERSION 并校验结构。
export function migrate(parsed) {
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    return corruptResult('state-not-object', { receivedType: Array.isArray(parsed) ? 'array' : typeof parsed });
  }

  const versionRaw = parsed.schemaVersion;
  let version;
  if (versionRaw === undefined || versionRaw === null) {
    version = 1; // 契约：缺省 schemaVersion 视为 1
  } else if (typeof versionRaw === 'number' && Number.isInteger(versionRaw) && versionRaw >= 1) {
    version = versionRaw;
  } else {
    return corruptResult('schema-version-invalid', { schemaVersion: versionRaw });
  }

  if (version > SCHEMA_VERSION) {
    return {
      ok: false,
      code: ERROR_CODES.SCHEMA_TOO_NEW,
      detail: { storedVersion: version, supportedVersion: SCHEMA_VERSION },
      state: createState(), // 只读降级：不解释外来 schema，也不写回覆盖
      readOnly: true,
      fromVersion: version,
      migrated: false,
    };
  }

  const fromVersion = version;
  let current = parsed;
  let stepVersion = version;
  while (stepVersion < SCHEMA_VERSION) {
    const step = MIGRATIONS[stepVersion];
    if (typeof step !== 'function') return corruptResult('missing-migration', { fromVersion: stepVersion });
    const next = step(current);
    if (!next || typeof next !== 'object' || Array.isArray(next)) {
      return corruptResult('migration-output-invalid', { fromVersion: stepVersion });
    }
    current = next;
    stepVersion += 1;
  }

  const validated = validateStateStructure(current);
  if (!validated.ok) return corruptResult('state-structure-invalid', validated.detail);

  return {
    ok: true,
    state: validated.state,
    readOnly: false,
    fromVersion,
    migrated: fromVersion !== SCHEMA_VERSION,
  };
}

// parseAndMigrate 接收原始字符串（storage 读出的值）。
export function parseAndMigrate(raw) {
  if (raw === null || raw === undefined) {
    return { ok: true, state: createState(), readOnly: false, fromVersion: SCHEMA_VERSION, migrated: false };
  }
  if (typeof raw !== 'string') {
    return corruptResult('raw-not-string', { receivedType: typeof raw });
  }
  if (raw.trim() === '') return corruptResult('raw-empty');

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    return corruptResult('json-parse-error', { message: messageOf(err) });
  }
  return migrate(parsed);
}

/* ----------------------------- 日志 ----------------------------- */

// 结构化日志：{ event, code, detail }；不静默吞错。
function defaultLog(entry) {
  const consoleObj = globalThis.console;
  if (!consoleObj) return;
  const level = entry.code === null || entry.code === undefined ? 'info' : 'warn';
  consoleObj[level]('[todo-store]', entry);
}

/* --------------------------- store 工厂 --------------------------- */

function assertStorage(storage) {
  if (!storage || typeof storage !== 'object') {
    throw new TypeError('createStore: 需要注入 storage 适配器（getItem/setItem/removeItem）');
  }
  for (const name of ['getItem', 'setItem', 'removeItem']) {
    if (typeof storage[name] !== 'function') {
      throw new TypeError(`createStore: storage.${name} 必须是函数`);
    }
  }
}

/**
 * createStore(storage) —— storage 为注入适配器：getItem / setItem / removeItem。
 * 所有变更 API 返回 { ok: true, state } | { ok: false, code, detail }；
 * 失败时内存态与持久化态均不变（原子写：一次 setItem 提交整份状态，成功后才提交内存态）。
 * options.log / options.now / options.makeId 为测试注入缝。
 */
export function createStore(storage, options = {}) {
  assertStorage(storage);

  const log = typeof options.log === 'function' ? options.log : defaultLog;
  const now = typeof options.now === 'function' ? options.now : undefined;
  const makeId = typeof options.makeId === 'function' ? options.makeId : undefined;
  const mutationOptions = { now, makeId };

  let state = createState();
  let readOnly = false;
  let loadStatus = { ok: true, code: null, detail: null };

  function emit(event, code, detail) {
    log({ event, code, detail });
  }

  function backupCorrupt(raw) {
    const key = `${CORRUPT_KEY_PREFIX}${Date.now()}`;
    let previousKey = null;
    try {
      previousKey = storage.getItem(CORRUPT_INDEX_KEY);
    } catch (err) {
      previousKey = null;
      emit('corrupt-backup-index-read-failed', ERROR_CODES.STORAGE_UNAVAILABLE, { message: messageOf(err) });
    }
    try {
      storage.setItem(key, raw);
      emit('corrupt-backup-written', null, { key, length: raw.length });
    } catch (err) {
      emit('corrupt-backup-write-failed', ERROR_CODES.STORAGE_UNAVAILABLE, { key, message: messageOf(err) });
      return { ok: false, key: null };
    }
    try {
      storage.setItem(CORRUPT_INDEX_KEY, key);
    } catch (err) {
      emit('corrupt-backup-index-write-failed', ERROR_CODES.STORAGE_UNAVAILABLE, { key, message: messageOf(err) });
    }
    if (previousKey && previousKey !== key) {
      try {
        storage.removeItem(previousKey); // 仅保留最近 1 份
        emit('corrupt-backup-pruned', null, { removed: previousKey });
      } catch (err) {
        emit('corrupt-backup-prune-failed', ERROR_CODES.STORAGE_UNAVAILABLE, {
          removed: previousKey,
          message: messageOf(err),
        });
      }
    }
    return { ok: true, key };
  }

  function load() {
    let raw;
    try {
      raw = storage.getItem(STORAGE_KEY);
    } catch (err) {
      state = createState();
      loadStatus = { ok: false, code: ERROR_CODES.STORAGE_UNAVAILABLE, detail: { phase: 'getItem', message: messageOf(err) } };
      emit('storage-unavailable', ERROR_CODES.STORAGE_UNAVAILABLE, loadStatus.detail);
      return;
    }

    const parsed = parseAndMigrate(raw);
    if (parsed.ok) {
      state = parsed.state;
      loadStatus = { ok: true, code: null, detail: null };
      if (parsed.migrated) {
        emit('schema-migrated', null, { fromVersion: parsed.fromVersion, toVersion: SCHEMA_VERSION });
      }
      return;
    }

    if (parsed.code === ERROR_CODES.SCHEMA_TOO_NEW) {
      readOnly = true; // 只读降级：任何变更都会被拒绝，绝不覆盖用户数据
      state = createState();
      loadStatus = { ok: false, code: parsed.code, detail: parsed.detail };
      emit('schema-too-new', parsed.code, parsed.detail);
      return;
    }

    const backup = backupCorrupt(typeof raw === 'string' ? raw : '');
    state = createState();
    loadStatus = {
      ok: false,
      code: parsed.code,
      detail: { ...parsed.detail, backupKey: backup.key, backupOk: backup.ok },
    };
    emit('storage-corrupt', parsed.code, loadStatus.detail);
  }

  function apply(event, mutation) {
    if (readOnly) {
      const failure = fail(ERROR_CODES.SCHEMA_TOO_NEW, {
        reason: 'read-only-degrade',
        storedVersion: loadStatus.detail ? loadStatus.detail.storedVersion : null,
      });
      emit(event, failure.code, failure.detail);
      return failure;
    }

    const result = mutation(state);
    if (!result.ok) {
      emit(event, result.code, result.detail === undefined ? null : result.detail);
      return result;
    }

    try {
      storage.setItem(STORAGE_KEY, serialize(result.state));
    } catch (err) {
      const failure = fail(ERROR_CODES.STORAGE_UNAVAILABLE, {
        phase: 'setItem',
        operation: event,
        message: messageOf(err),
      });
      emit(event, failure.code, failure.detail);
      return failure; // 内存态保持上次已提交状态
    }

    state = result.state;
    emit(event, null, { count: state.todos.length });
    return { ok: true, state };
  }

  load();

  return {
    getState: () => state,
    status: () => ({
      storageKey: STORAGE_KEY,
      schemaVersion: SCHEMA_VERSION,
      capacityLimit: CAPACITY_LIMIT,
      count: state.todos.length,
      readOnly,
      load: loadStatus,
    }),
    add: (title) => apply('add', (current) => addTodo(current, title, mutationOptions)),
    toggle: (id) => apply('toggle', (current) => toggleTodo(current, id)),
    remove: (id) => apply('remove', (current) => removeTodo(current, id)),
  };
}

read_file: src/storage.js

/**
 * 浏览器存储适配器：本项目**唯一**接触全局 localStorage 的模块。
 *
 * 只做三方法原样转发（getItem / setItem / removeItem），不含任何序列化、校验或字段逻辑；
 * 由 src/app.js 注入 createStore(storage)，使 app.js 与 store.js 都不直接触碰 localStorage。
 * 方法体内部才访问 localStorage：隐私模式 / 配额已满时浏览器会在此抛异常，
 * 由 store.js 统一捕获并归一化为 STORAGE_UNAVAILABLE（界面继续可用）。
 */
export const browserStorage = {
  getItem(key) {
    return globalThis.localStorage.getItem(key);
  },
  setItem(key, value) {
    globalThis.localStorage.setItem(key, value);
  },
  removeItem(key) {
    globalThis.localStorage.removeItem(key);
  },
};

read_file: src/app.js

/**
 * 交互层：只做 DOM 渲染与事件绑定。
 * 依赖方向：app.js → store.js（数据与校验）、app.js → storage.js（浏览器适配器注入）。
 * 不直接读写 localStorage、不解析/构造持久化 JSON、不自行校验或改状态。
 * 渲染一律用 textContent / createElement，绝不把用户输入拼进 HTML。
 */
import { CAPACITY_LIMIT, ERROR_CODES, MAX_TITLE_LEN, createStore } from './store.js';
import { browserStorage } from './storage.js';

// 错误码 → 用户可读提示。store 的每个失败码都必须有可见文案，不允许只打 console。
const MESSAGES = Object.freeze({
  [ERROR_CODES.TITLE_EMPTY]: '标题不能为空，只输入空白也不行。',
  [ERROR_CODES.TITLE_TOO_LONG]: `标题最多 ${MAX_TITLE_LEN} 个字符（按码点计，表情算 1 个）。`,
  [ERROR_CODES.STORAGE_UNAVAILABLE]: '浏览器存储不可用（隐私模式或存储配额已满），本次修改未保存。',
  [ERROR_CODES.STORAGE_CORRUPT]: '本地数据已损坏：原始内容已备份，已从空列表开始。',
  [ERROR_CODES.SCHEMA_TOO_NEW]: '本地数据由更新版本的程序写入，当前为只读模式，不会覆盖你的数据。',
  [ERROR_CODES.TODO_NOT_FOUND]: '这条待办已不存在，列表已刷新。',
  [ERROR_CODES.CAPACITY_EXCEEDED]: `待办数量已达上限（${CAPACITY_LIMIT} 条），请先删除一些。`,
});

const FALLBACK_MESSAGE = '操作失败，请重试。';

function messageFor(code) {
  return MESSAGES[code] || FALLBACK_MESSAGE;
}

function requireElement(id) {
  const node = document.getElementById(id);
  if (!node) throw new Error(`缺少必要的 DOM 节点：#${id}`);
  return node;
}

const form = requireElement('new-todo-form');
const input = requireElement('new-todo');
const submitButton = requireElement('new-todo-submit');
const inputHint = requireElement('input-hint');
const errorBanner = requireElement('error-banner');
const notice = requireElement('notice');
const panel = requireElement('todo-panel');
const loadingState = requireElement('loading-state');
const emptyState = requireElement('empty-state');
const list = requireElement('todo-list');
const listSummary = requireElement('list-summary');

const store = createStore(browserStorage);

// 只保存「加载失败码」这一项视图关注点，业务状态一律来自 store.getState()。
let loadErrorCode = null;
let noticeTimer = null;

/* ------------------------------ 渲染 ------------------------------ */

function renderItem(todo) {
  const item = document.createElement('li');
  item.className = 'todo-item';
  item.dataset.id = todo.id;
  if (todo.done) item.dataset.done = 'true';

  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.className = 'todo-checkbox';
  checkbox.checked = todo.done;
  checkbox.dataset.action = 'toggle';
  // 动作 + 目标一起播报，避免只读出「复选框」而不知操作对象
  checkbox.setAttribute('aria-label', `${todo.done ? '取消完成' : '标记完成'}：${todo.title}`);

  const title = document.createElement('span');
  title.className = 'todo-title';
  title.textContent = todo.title; // 只写文本节点：用户输入永远不会被当作 HTML 解析

  const removeButton = document.createElement('button');
  removeButton.type = 'button';
  removeButton.className = 'todo-remove';
  removeButton.dataset.action = 'remove';
  removeButton.setAttribute('aria-label', `删除：${todo.title}`);
  removeButton.textContent = '删除';

  item.append(checkbox, title, removeButton);
  return item;
}

// 单向 render(state)：DOM 完全由 state 派生，不做增量补丁，避免界面与数据漂移。
function render(state) {
  const todos = state.todos;
  list.textContent = '';

  for (const todo of todos) list.append(renderItem(todo));

  const doneCount = todos.filter((todo) => todo.done).length;
  listSummary.textContent = todos.length === 0 ? '' : `共 ${todos.length} 条，已完成 ${doneCount} 条。`;
  listSummary.hidden = todos.length === 0;

  loadingState.hidden = true;
  emptyState.hidden = !(todos.length === 0 && loadErrorCode === null);
  panel.dataset.state = loadErrorCode !== null ? 'error' : todos.length === 0 ? 'empty' : 'ready';
}

function showNotice(text, tone) {
  notice.textContent = text;
  notice.dataset.tone = tone;
  notice.hidden = false;
  if (noticeTimer !== null) globalThis.clearTimeout(noticeTimer);
  noticeTimer = globalThis.setTimeout(() => {
    notice.hidden = true;
    noticeTimer = null;
  }, 4000);
}

function hideNotice() {
  if (noticeTimer !== null) globalThis.clearTimeout(noticeTimer);
  noticeTimer = null;
  notice.hidden = true;
}

// 错误态：加载期失败（损坏 / 存储不可用 / 版本过新）用常驻错误条，不用 4 秒后消失的提示。
function showErrorBanner(code) {
  errorBanner.textContent = messageFor(code);
  errorBanner.hidden = false;
  loadErrorCode = code;
}

function setReadOnly(readOnly) {
  input.disabled = readOnly;
  submitButton.disabled = readOnly;
  for (const node of [input, submitButton]) {
    if (readOnly) node.setAttribute('aria-disabled', 'true');
    else node.removeAttribute('aria-disabled');
  }
}

function updateHint() {
  const length = Array.from(input.value.trim()).length;
  const over = length > MAX_TITLE_LEN;
  inputHint.textContent = over
    ? `已超出上限：${length} / ${MAX_TITLE_LEN} 个字符（按码点计）。`
    : `${length} / ${MAX_TITLE_LEN} 个字符（按码点计，表情算 1 个）。回车或点击「添加」提交。`;
  inputHint.dataset.tone = over ? 'error' : 'info';
}

function markInputInvalid(invalid) {
  if (invalid) input.setAttribute('aria-invalid', 'true');
  else input.removeAttribute('aria-invalid');
}

// 重渲染后按 id 找回同一条目的勾选框并聚焦，避免键盘用户操作一条就被甩回输入框。
function focusItemCheckbox(id) {
  for (const item of list.children) {
    if (item.dataset.id !== id) continue;
    const checkbox = item.querySelector('.todo-checkbox');
    if (checkbox) checkbox.focus();
    return;
  }
  input.focus();
}

/* ------------------------------ 事件 ------------------------------ */

// 变更结果统一出口：
// - 成功 → 单向重渲染 + 状态提示 + 可选焦点恢复；
// - 失败 → 可读提示 + 回滚界面到 store 真实状态（例如勾选框已被浏览器抢先翻转）。
function handleResult(result, successMessage, afterRender) {
  if (!result.ok) {
    showNotice(messageFor(result.code), 'error');
    render(store.getState());
    if (result.code === ERROR_CODES.TITLE_EMPTY || result.code === ERROR_CODES.TITLE_TOO_LONG) {
      markInputInvalid(true);
      input.focus();
    }
    return;
  }
  markInputInvalid(false);
  render(result.state);
  showNotice(successMessage, 'ok');
  if (typeof afterRender === 'function') afterRender();
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  if (store.status().readOnly) {
    showNotice(messageFor(ERROR_CODES.SCHEMA_TOO_NEW), 'error');
    return;
  }
  const result = store.add(input.value);
  if (result.ok) {
    input.value = '';
    hideNotice();
  }
  updateHint();
  handleResult(result, '已添加。', () => input.focus());
});

input.addEventListener('input', () => {
  markInputInvalid(false);
  updateHint();
});

// 事件委托：列表整体重渲染后无需重新绑定监听器。
list.addEventListener('change', (event) => {
  const target = event.target;
  if (!(target instanceof HTMLInputElement) || target.dataset.action !== 'toggle') return;
  const item = target.closest('.todo-item');
  if (!item) return;
  const id = item.dataset.id;
  const result = store.toggle(id);
  if (!result.ok) {
    handleResult(result, '', null);
    return;
  }
  const toggled = result.state.todos.find((entry) => entry.id === id);
  handleResult(result, toggled && toggled.done ? '已标记完成。' : '已取消完成。', () => focusItemCheckbox(id));
});

list.addEventListener('click', (event) => {
  const target = event.target;
  if (!(target instanceof HTMLButtonElement) || target.dataset.action !== 'remove') return;
  const item = target.closest('.todo-item');
  if (!item) return;
  handleResult(store.remove(item.dataset.id), '已删除。', () => input.focus());
});

/* ------------------------------ 启动 ------------------------------ */

function init() {
  // 加载态先落地（HTML 里也预置了 data-state="loading"），随后立刻由 store 的真实状态接管。
  loadingState.hidden = false;
  emptyState.hidden = true;
  panel.dataset.state = 'loading';
  updateHint();

  const status = store.status();
  setReadOnly(status.readOnly);
  if (status.load && status.load.code) showErrorBanner(status.load.code);
  else errorBanner.hidden = true;

  render(store.getState());
}

init();

