/**
 * 截图脚本（真实浏览器渲染 + 真实静态服务）：`node tests/scripts/take-screenshots.mjs`
 *
 * 做什么：
 *  1) 用 README 同款命令 `python3 -m http.server 8000` 启动真实静态服务（cwd = 项目根）；
 *  2) 对每个截图状态，先用无头 Chrome `--dump-dom` 打开 `tests/screenshot-seed.html?state=<s>`
 *     （该页写入真实 localStorage 后 `location.replace` 到真实 `index.html`），
 *     断言「跳转后的 DOM 确实处于目标状态」——这一步防止拍到空白种子页却当成产品页；
 *  3) 再用同一个 URL 跑 `--screenshot=`，把 PNG 落到 `tests/screenshots/`；
 *  4) 校验 PNG 文件签名与 IHDR 宽高是否等于 `--window-size`（证明是真实渲染出来的图，不是空文件）。
 *
 * 只写 `tests/screenshots/` 内的 PNG；不改产品代码、不联网、不写盘到别处。
 * 退出码：0 = 全部状态截图成功且断言通过；1 = 任一失败（含缺 Chrome / 断言不符）。
 */
import { spawn } from 'node:child_process';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, statSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('../../', import.meta.url));
const OUT_DIR = join(ROOT, 'tests/screenshots');
const PORT = 8000;
const BASE = `http://127.0.0.1:${PORT}`;
const CHROME = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';

/**
 * 每个状态：
 * - state  → 种子页参数
 * - size   → `--window-size`
 * - file   → 输出文件名
 * - expect → 跳转后 DOM 必须满足的断言（每条都是 [正则, 人类可读说明]）
 * - 同时要求 dump-dom 里出现产品页特征（`id="new-todo-form"`），确保跳转已发生
 */
const SHOTS = [
  {
    state: 'empty',
    size: '1280,800',
    file: 'empty-1280x800.png',
    label: '空态（无待办）',
    expect: [
      [/id="new-todo-form"/, '已跳转到产品页 index.html'],
      [/id="todo-panel"[^>]*data-state="empty"/, '面板 data-state="empty"'],
      [/id="empty-state"(?![^>]*\bhidden\b)/, '空态文案可见（无 hidden）'],
      [/id="loading-state"[^>]*\bhidden\b/, '加载态已收起'],
      [/id="error-banner"[^>]*\bhidden\b/, '无错误条'],
    ],
  },
  {
    state: 'ready',
    size: '1280,800',
    file: 'ready-1280x800.png',
    label: '正常态（2 条待办，其中 1 条已完成）',
    expect: [
      [/id="todo-panel"[^>]*data-state="ready"/, '面板 data-state="ready"'],
      [/class="todo-item"[^>]*data-done="true"/, '存在已完成条目（data-done=true）'],
      [/class="todo-item"/, '列表已渲染条目'],
      [/共 2 条，已完成 1 条。/, '摘要显示共 2 条 / 已完成 1 条'],
      [/id="empty-state"[^>]*\bhidden\b/, '空态已隐藏'],
    ],
  },
  {
    state: 'corrupt',
    size: '1280,800',
    file: 'corrupt-1280x800.png',
    label: '损坏数据错误态（坏 JSON → 备份 + 空列表）',
    expect: [
      [/id="error-banner"[^>]*role="alert"(?![^>]*\bhidden\b)/, '常驻错误条可见且 role="alert"'],
      [/本地数据已损坏/, '错误条文案含「本地数据已损坏」'],
      [/id="todo-panel"[^>]*data-state="error"/, '面板 data-state="error"'],
    ],
  },
  {
    state: 'readonly',
    size: '1280,800',
    file: 'readonly-1280x800.png',
    label: '只读降级态（schemaVersion 过新）',
    expect: [
      [/只读模式/, '错误条文案含「只读模式」'],
      [/id="new-todo-submit"[^>]*\bdisabled\b/, '提交按钮已禁用'],
      [/id="new-todo"[^>]*\bdisabled\b/, '输入框已禁用'],
      [/id="todo-panel"[^>]*data-state="error"/, '面板 data-state="error"'],
    ],
  },
  {
    state: 'empty',
    size: '320,800',
    file: 'empty-320x800.png',
    label: '窄屏 320px · 空态',
    expect: [
      [/id="todo-panel"[^>]*data-state="empty"/, '面板 data-state="empty"'],
      [/id="empty-state"(?![^>]*\bhidden\b)/, '空态文案可见'],
    ],
  },
  {
    state: 'ready',
    size: '320,800',
    file: 'ready-320x800.png',
    label: '窄屏 320px · 正常态（含已完成条目）',
    expect: [
      [/id="todo-panel"[^>]*data-state="ready"/, '面板 data-state="ready"'],
      [/class="todo-item"[^>]*data-done="true"/, '存在已完成条目'],
    ],
  },
];

function run(command, args, timeoutMs = 90000) {
  return new Promise((resolve) => {
    const child = spawn(command, args, { cwd: ROOT });
    let stdout = '';
    let stderr = '';
    const timer = setTimeout(() => child.kill('SIGKILL'), timeoutMs);
    child.stdout.on('data', (chunk) => {
      stdout += chunk;
    });
    child.stderr.on('data', (chunk) => {
      stderr += chunk;
    });
    child.on('error', (error) => {
      clearTimeout(timer);
      resolve({ code: -1, stdout, stderr: stderr + error.message });
    });
    child.on('close', (code) => {
      clearTimeout(timer);
      resolve({ code, stdout, stderr });
    });
  });
}

async function waitForServer(timeoutMs = 10000) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    try {
      const response = await fetch(`${BASE}/`, { redirect: 'manual' });
      if (response.status === 200) return true;
    } catch {
      // 继续等
    }
    await new Promise((resolve) => setTimeout(resolve, 150));
  }
  return false;
}

/** 读取 PNG 的 IHDR 宽高（真实图像校验，防止空文件/非 PNG 冒充截图） */
function pngSize(buffer) {
  const signature = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a];
  for (let i = 0; i < signature.length; i += 1) {
    if (buffer[i] !== signature[i]) return null;
  }
  return { width: buffer.readUInt32BE(16), height: buffer.readUInt32BE(20) };
}

function decodeEntities(html) {
  return html.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"');
}

async function main() {
  console.log('== 环境 ==');
  console.log(`node ${process.version} / cwd=${ROOT}`);
  if (!existsSync(CHROME)) {
    console.log(`FAIL  未找到 Chrome（${CHROME}）：本次截图未生成。`);
    return 1;
  }
  console.log(`chrome: ${CHROME}`);
  mkdirSync(OUT_DIR, { recursive: true });

  console.log('\n== 启动真实静态服务（README 同款命令） ==');
  const server = spawn('python3', ['-m', 'http.server', String(PORT)], { cwd: ROOT });
  let serverLog = '';
  server.stdout.on('data', (chunk) => {
    serverLog += chunk;
  });
  server.stderr.on('data', (chunk) => {
    serverLog += chunk;
  });

  let failed = 0;
  try {
    if (!await waitForServer()) {
      console.log(`FAIL  静态服务 10s 内未就绪：${serverLog.trim() || '(无输出)'}`);
      return 1;
    }
    console.log(`PASS  python3 -m http.server ${PORT} 已就绪：${BASE}/\n`);

    console.log('== 逐状态：先断言跳转后 DOM，再截图并校验 PNG ==');
    for (const shot of SHOTS) {
      const url = `${BASE}/tests/screenshot-seed.html?state=${shot.state}`;
      const profile = mkdtempSync(join(tmpdir(), 'todo-shot-'));

      // 1) dump-dom：确认跳转发生且页面处于目标状态
      const dump = await run(CHROME, [
        '--headless=new',
        '--disable-gpu',
        '--no-first-run',
        '--no-default-browser-check',
        '--disable-extensions',
        '--hide-scrollbars',
        '--force-device-scale-factor=1',
        `--user-data-dir=${profile}`,
        `--window-size=${shot.size}`,
        '--virtual-time-budget=8000',
        '--dump-dom',
        url,
      ]);
      const dom = decodeEntities(dump.stdout);
      const domProblems = shot.expect.filter(([pattern]) => !pattern.test(dom)).map(([, label]) => label);
      if (domProblems.length > 0) {
        console.log(`FAIL  ${shot.file}  DOM 断言未通过（${shot.label}）：${domProblems.join(' / ')}`);
        failed += 1;
        rmSync(profile, { recursive: true, force: true });
        continue;
      }

      // 2) 截图（真实浏览器渲染 → PNG）
      const target = join(OUT_DIR, shot.file);
      const shot2 = await run(CHROME, [
        '--headless=new',
        '--disable-gpu',
        '--no-first-run',
        '--no-default-browser-check',
        '--disable-extensions',
        '--hide-scrollbars',
        '--force-device-scale-factor=1',
        `--user-data-dir=${profile}`,
        `--window-size=${shot.size}`,
        '--virtual-time-budget=8000',
        `--screenshot=${target}`,
        url,
      ]);
      rmSync(profile, { recursive: true, force: true });

      if (!existsSync(target)) {
        console.log(`FAIL  ${shot.file}  未生成（Chrome 退出码 ${shot2.code}）：${shot2.stderr.slice(0, 300)}`);
        failed += 1;
        continue;
      }
      const buffer = readFileSync(target);
      const size = pngSize(buffer);
      const [expectedWidth, expectedHeight] = shot.size.split(',').map(Number);
      if (!size) {
        console.log(`FAIL  ${shot.file}  不是合法 PNG（签名不符）`);
        failed += 1;
        continue;
      }
      if (size.width !== expectedWidth || size.height !== expectedHeight) {
        console.log(`FAIL  ${shot.file}  尺寸 ${size.width}x${size.height} 与 --window-size ${shot.size} 不符`);
        failed += 1;
        continue;
      }
      console.log(
        `PASS  ${shot.file}  ${shot.label}  → ${size.width}x${size.height} / ${buffer.length} 字节 / DOM 断言 ${shot.expect.length} 条全过`,
      );
      void statSync(target);
    }
  } finally {
    server.kill('SIGTERM');
    await new Promise((resolve) => setTimeout(resolve, 200));
    if (!server.killed) server.kill('SIGKILL');
  }

  console.log('');
  console.log(failed === 0 ? `结论：${SHOTS.length} 张截图全部生成并通过校验（${OUT_DIR}）。` : `结论：${failed} 张失败。`);
  return failed === 0 ? 0 : 1;
}

process.exitCode = await main();

