/**
 * 验收方（Proof）独立核对脚本 —— node docs/verification/run-independent-demo.mjs
 *
 * 自包含、有超时、有收尾，不驻留：
 *  1) 先检查 8123 端口是否已被占用（占用则立即失败退出，不改用其它端口静默继续）；
 *  2) spawn `python3 -m http.server 8123`（cwd = 项目根；stdout/stderr 收集在内存，不写项目外日志）；
 *  3) 10s 内轮询 `/` 就绪；
 *  4) 真实 HTTP 状态码 / Content-Type 核对（含不存在的资源必须是 404）；
 *  5) 无头 Chrome `--dump-dom` 打开本角色自写的驱动页 docs/verification/independent-demo.html，
 *     取回它在真实浏览器内核里产生的 PASS/FAIL 报告（真实点击 / 真实表单提交 / 真实 localStorage / 真实重载）；
 *  6) 逐个状态：先断言「种子页跳转后的 DOM 处于目标状态」，再 `--screenshot` 截图到
 *     docs/verification/screenshots/，并校验 PNG 签名与 IHDR 宽高；
 *  7) 从 styles.css 解析色值，按 WCAG 相对亮度公式计算对比度并断言 ≥ 4.5:1。
 * finally：SIGTERM → SIGKILL 关闭服务并等待退出；180s 总超时强制退出。
 * 除 docs/verification/screenshots/*.png 外不写盘；不改产品代码。
 */
import { spawn } from 'node:child_process';
import { createServer } from 'node:net';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('../../', import.meta.url));
const PORT = 8123;
const BASE = `http://127.0.0.1:${PORT}`;
const CHROME = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const OUT_DIR = join(ROOT, 'docs/verification/screenshots');
const DRIVER = `${BASE}/docs/verification/independent-demo.html`;

let pass = 0;
let fail = 0;
let server = null;

function ok(condition, name, detail = '') {
  if (condition) {
    pass += 1;
    console.log(`PASS  ${name}${detail ? `  —— ${detail}` : ''}`);
  } else {
    fail += 1;
    console.log(`FAIL  ${name}${detail ? `  —— ${detail}` : ''}`);
  }
  return condition;
}

function run(command, args, timeoutMs = 60000) {
  return new Promise((resolve) => {
    const child = spawn(command, args, { cwd: ROOT });
    let stdout = '';
    let stderr = '';
    const timer = setTimeout(() => child.kill('SIGKILL'), timeoutMs);
    child.stdout.on('data', (chunk) => { stdout += chunk; });
    child.stderr.on('data', (chunk) => { stderr += chunk; });
    child.on('error', (error) => { clearTimeout(timer); resolve({ code: -1, stdout, stderr: stderr + error.message }); });
    child.on('close', (code) => { clearTimeout(timer); resolve({ code, stdout, stderr }); });
  });
}

function portFree(port) {
  return new Promise((resolve) => {
    const tester = createServer();
    tester.once('error', () => resolve(false));
    tester.once('listening', () => tester.close(() => resolve(true)));
    tester.listen(port, '127.0.0.1');
  });
}

async function waitForServer(timeoutMs = 10000) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    try {
      const response = await fetch(`${BASE}/`, { redirect: 'manual' });
      if (response.status === 200) return true;
    } catch {
      // 服务还没起来，继续等
    }
    await new Promise((resolve) => setTimeout(resolve, 150));
  }
  return false;
}

async function stopServer() {
  if (!server) return;
  const exited = new Promise((resolve) => server.once('close', resolve));
  server.kill('SIGTERM');
  const raced = await Promise.race([
    exited.then(() => 'closed'),
    new Promise((resolve) => setTimeout(() => resolve('timeout'), 3000)),
  ]);
  if (raced === 'timeout') {
    server.kill('SIGKILL');
    await exited;
  }
  server = null;
}

function decodeEntities(html) {
  return html.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'");
}

function pngSize(buffer) {
  const signature = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a];
  for (let i = 0; i < signature.length; i += 1) if (buffer[i] !== signature[i]) return null;
  return { width: buffer.readUInt32BE(16), height: buffer.readUInt32BE(20) };
}

/* ---------------- WCAG 对比度（由 styles.css 的真实色值计算） ---------------- */
function luminance(hex) {
  const value = hex.replace('#', '');
  const channels = [0, 2, 4].map((start) => parseInt(value.slice(start, start + 2), 16) / 255);
  const [r, g, b] = channels.map((c) => (c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4));
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

function contrast(fg, bg) {
  const a = luminance(fg);
  const b = luminance(bg);
  const lighter = Math.max(a, b);
  const darker = Math.min(a, b);
  return (lighter + 0.05) / (darker + 0.05);
}

const SEEDS = [
  {
    seed: 'empty',
    size: '1280,800',
    file: 'verifier-empty-1280x800.png',
    label: '空态 · 1280x800',
    expect: [
      [/id="new-todo-form"/, '已跳转到真实产品页'],
      [/id="todo-panel"[^>]*data-state="empty"/, '面板 data-state=empty'],
      [/id="empty-state"(?![^>]*\bhidden\b)/, '空态文案可见'],
    ],
  },
  {
    seed: 'ready',
    size: '1280,800',
    file: 'verifier-ready-1280x800.png',
    label: '正常态（2 条，1 条已完成） · 1280x800',
    expect: [
      [/id="todo-panel"[^>]*data-state="ready"/, '面板 data-state=ready'],
      [/class="todo-item"[^>]*data-done="true"/, '存在已完成条目'],
      [/共 2 条，已完成 1 条。/, '摘要正确'],
    ],
  },
  {
    seed: 'corrupt',
    size: '1280,800',
    file: 'verifier-corrupt-1280x800.png',
    label: '损坏数据错误态 · 1280x800',
    expect: [
      [/id="error-banner"[^>]*role="alert"(?![^>]*\bhidden\b)/, '常驻错误条可见且 role=alert'],
      [/本地数据已损坏/, '错误文案可见'],
      [/id="todo-panel"[^>]*data-state="error"/, '面板 data-state=error'],
    ],
  },
  {
    seed: 'readonly',
    size: '1280,800',
    file: 'verifier-readonly-1280x800.png',
    label: '只读降级态 · 1280x800',
    expect: [
      [/只读模式/, '错误文案含只读模式'],
      [/id="new-todo"[^>]*\bdisabled\b/, '输入框已禁用'],
      [/id="new-todo-submit"[^>]*\bdisabled\b/, '提交按钮已禁用'],
    ],
  },
  {
    seed: 'ready',
    size: '320,800',
    file: 'verifier-ready-320x800.png',
    label: '正常态 · 窄屏 320x800',
    expect: [
      [/id="todo-panel"[^>]*data-state="ready"/, '面板 data-state=ready'],
      [/class="todo-item"[^>]*data-done="true"/, '存在已完成条目'],
    ],
  },
];

async function main() {
  console.log('== 0. 环境 ==');
  console.log(`node ${process.version} / cwd=${ROOT}`);
  if (!existsSync(CHROME)) {
    console.log(`FAIL  未找到 Chrome（${CHROME}）`);
    return 1;
  }
  const ready = await portFree(PORT);
  if (!ready) {
    console.log(`FAIL  端口 ${PORT} 已被占用：为避免与其它进程冲突，本脚本直接退出，不改用其它端口。`);
    return 1;
  }

  console.log('\n== 1. 真实启动静态服务（README 同款命令，脚本内收尾） ==');
  server = spawn('python3', ['-m', 'http.server', String(PORT)], { cwd: ROOT });
  let serverLog = '';
  server.stdout.on('data', (chunk) => { serverLog += chunk; });
  server.stderr.on('data', (chunk) => { serverLog += chunk; });

  try {
    if (!await waitForServer()) {
      console.log(`FAIL  静态服务 10s 内未就绪：${serverLog.trim() || '(无输出)'}`);
      return 1;
    }
    ok(true, `python3 -m http.server ${PORT} 就绪`, `访问地址 ${BASE}/`);

    console.log('\n== 2. 真实 HTTP 核对 ==');
    for (const [path, expectType] of [
