<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>verifier 独立演示驱动 · todo-spa-genesis</title>
<style>
  body { font: 14px/1.6 system-ui, sans-serif; margin: 16px; }
  pre { white-space: pre-wrap; background: #f5f7fb; padding: 12px; border-radius: 8px; }
</style>
</head>
<body>
<h1>verifier 独立演示驱动（Proof / 验收）</h1>
<p>用途：在真实浏览器内核里驱动真实产品页 <code>/index.html</code>（同源 iframe + 真实点击 / 真实表单提交 /
真实 <code>localStorage</code> / 真实导航重载）。本文件由验收角色独立编写，<strong>不是产品代码</strong>，
也不复用实现方的 <code>tests/e2e-browser.html</code>。两种模式：</p>
<ul>
  <li>无参数：跑验收交互序列，把 PASS/FAIL 报告写进 <code>#report</code>（用 Chrome <code>--dump-dom</code> 取回）；</li>
  <li><code>?seed=empty|ready|corrupt|readonly</code>：写入种子 state 后跳转真实 <code>/index.html</code>（供截图）。</li>
</ul>
<pre id="report">运行中…</pre>
<script>
(async () => {
  const report = document.getElementById('report');
  const KEY = 'todo.spa.state';
  const BACKUP_PREFIX = 'todo.spa.state.corrupt.';
  const lines = [];
  let passCount = 0;
  let failCount = 0;

  function log(ok, name, detail) {
    if (ok) passCount += 1;
    else failCount += 1;
    lines.push(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? `  —— ${detail}` : ''}`);
    report.textContent = lines.join('\n');
  }

  function allKeys() {
    const keys = [];
    for (let i = 0; i < localStorage.length; i += 1) keys.push(localStorage.key(i));
    return keys;
  }

  function clearState() {
    for (const key of allKeys()) if (key.startsWith(KEY)) localStorage.removeItem(key);
  }

  const seed = new URLSearchParams(location.search).get('seed');
  if (seed) {
    clearState();
    if (seed === 'ready') {
      localStorage.setItem(KEY, JSON.stringify({
        schemaVersion: 1,
        todos: [
          { id: 'seed-1', title: '买菜（验收演示）', done: false, createdAt: '2024-01-01T00:00:00.000Z' },
          { id: 'seed-2', title: '写验收报告', done: true, createdAt: '2024-01-02T00:00:00.000Z' },
        ],
      }));
    } else if (seed === 'corrupt') {
      localStorage.setItem(KEY, '{"schemaVersion":1,"todos":[');
    } else if (seed === 'readonly') {
      localStorage.setItem(KEY, JSON.stringify({ schemaVersion: 999, todos: [] }));
    }
    location.replace('/index.html');
    return;
  }

  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

  try {
    const frame = document.createElement('iframe');
    frame.width = '1000';
    frame.height = '700';
    frame.src = '/index.html';
    const firstLoad = new Promise((resolve) => frame.addEventListener('load', resolve, { once: true }));
    document.body.appendChild(frame);
    await firstLoad;
    await sleep(120);

    const doc = () => frame.contentDocument;
    const win = () => frame.contentWindow;
    const $(id) => doc().getElementById(id);
    const panelState = () => $('todo-panel').dataset.state;
    const items = () => Array.from(doc().querySelectorAll('#todo-list .todo-item'));
    const titlesAndDone = () => items().map((item) => [
      item.querySelector('.todo-title').textContent,
      item.dataset.done === 'true',
    ]);
    const storedRaw = () => localStorage.getItem(KEY);
    const storedCount = () => {
      const parsed = JSON.parse(storedRaw() || 'null');
      return parsed && Array.isArray(parsed.todos) ? parsed.todos.length : null;
    };
    const noticeText = () => ($('notice').hidden ? '' : $('notice').textContent);

    async function reload() {
      frame.src = `/index.html?reload=${Date.now()}`;
      await new Promise((resolve) => frame.addEventListener('load', resolve, { once: true }));
      await sleep(140);
    }

    async function submit(value) {
      const d = doc();
      const input = d.getElementById('new-todo');
      input.value = value;
      input.dispatchEvent(new win().Event('input', { bubbles: true }));
      d.getElementById('new-todo-form').requestSubmit();
      await sleep(90);
    }

    // 路径1 空态
    clearState();
    await reload();
    log(
      panelState() === 'empty' && items().length === 0 && !$('empty-state').hidden && $('loading-state').hidden,
      '路径1 空态',
      `panel=${panelState()} / 列表 ${items().length} 条 / 空态可见=${!$('empty-state').hidden} / 加载态收起=${$('loading-state').hidden}`,
    );

    // 路径2 新增
    await submit('  验收演示甲  ');
    let state = JSON.parse(storedRaw());
    log(
      items().length === 1 && panelState() === 'ready' && state.todos.length === 1
        && state.todos[0].title === '验收演示甲' && noticeText().includes('已添加') && $('new-todo').value === '',
      '路径2 新增',
      `列表 ${items().length} 条 / panel=${panelState()} / 持久化 title=${JSON.stringify(state.todos[0].title)} / 提示「${noticeText()}」/ 输入已清空`,
    );

    // 路径3 标记完成
    items()[0].querySelector('.todo-checkbox').click();
    await sleep(90);
    state = JSON.parse(storedRaw());
    log(
      items()[0].dataset.done === 'true' && state.todos[0].done === true && noticeText().includes('已标记完成'),
      '路径3 标记完成',
      `data-done=${items()[0].dataset.done} / 持久化 done=${state.todos[0].done} / 提示「${noticeText()}」`,
    );

    // 路径4 取消完成
    items()[0].querySelector('.todo-checkbox').click();
    await sleep(90);
    state = JSON.parse(storedRaw());
    log(
      items()[0].dataset.done === undefined && state.todos[0].done === false && noticeText().includes('已取消完成'),
      '路径4 取消完成',
      `data-done=${items()[0].dataset.done} / 持久化 done=${state.todos[0].done} / 提示「${noticeText()}」`,
    );

    // 路径5 删除
    items()[0].querySelector('.todo-remove').click();
    await sleep(90);
    state = JSON.parse(storedRaw());
    log(
      items().length === 0 && panelState() === 'empty' && state.todos.length === 0 && noticeText().includes('已删除'),
      '路径5 删除',
      `列表 ${items().length} 条 / panel=${panelState()} / 持久化 ${state.todos.length} 条 / 提示「${noticeText()}」`,
    );

    // 路径6 刷新恢复
    await submit('甲');
    await submit('乙');
    items()[1].querySelector('.todo-checkbox').click();
    await sleep(90);
    const beforeReload = titlesAndDone();
    await reload();
    const afterReload = titlesAndDone();
    log(
      JSON.stringify(beforeReload) === JSON.stringify([['甲', false], ['乙', true]])
        && JSON.stringify(afterReload) === JSON.stringify(beforeReload),
      '路径6 刷新恢复',
      `重载前 ${JSON.stringify(beforeReload)} / 重载后 ${JSON.stringify(afterReload)}`,
    );

    // 路径7 纯空白标题
    const beforeBlank = storedRaw();
    await submit('   \u3000 ');
    log(
      items().length === 2 && storedRaw() === beforeBlank && noticeText().includes('标题不能为空')
        && $('new-todo').getAttribute('aria-invalid') === 'true',
      '路径7 纯空白标题',
      `提示「${noticeText()}」/ aria-invalid=${$('new-todo').getAttribute('aria-invalid')} / 持久化逐字节不变=${storedRaw() === beforeBlank}`,
    );

    // 路径8 201 码点
    const beforeLong = storedRaw();
    await submit('😀'.repeat(201));
    log(
      items().length === 2 && storedRaw() === beforeLong && noticeText().includes('最多 200'),
      '路径8 201 码点',
      `提示「${noticeText()}」/ 持久化逐字节不变=${storedRaw() === beforeLong}`,
    );

    // 路径9 XSS 载荷
    await submit('<img src=x onerror="alert(1)">');
    const xssItem = items()[items().length - 1];
    log(
      xssItem.querySelector('img') === null
        && xssItem.querySelector('.todo-title').textContent === '<img src=x onerror="alert(1)">',
      '路径9 XSS 载荷按文本渲染',
      `列表内 img 元素=${xssItem.querySelector('img')} / 标题文本=${xssItem.querySelector('.todo-title').textContent}`,
    );

    // 路径10 损坏数据
    localStorage.setItem(KEY, '{"schemaVersion":1,"todos":[');
    await reload();
    const backupKeys = allKeys().filter((key) => key.startsWith(BACKUP_PREFIX));
    const banner = $('error-banner');
    log(
      !banner.hidden && banner.textContent.includes('本地数据已损坏') && items().length === 0 && backupKeys.length === 1,
      '路径10 损坏数据降级',
      `错误条可见=true / 文案「${banner.textContent}」/ 列表 ${items().length} 条 / 备份键 ${backupKeys.join(',') || '(无)'}`,
    );

    // 路径11 损坏后仍可写
    await submit('损坏后仍可新增');
    log(
      items().length === 1 && storedCount() === 1,
      '路径11 损坏后仍可写',
      `列表 ${items().length} 条 / 持久化 ${storedCount()} 条`,
    );

    // 路径12 只读降级
    const readonlyRaw = JSON.stringify({
      schemaVersion: 999,
      todos: [{ id: 'keep-1', title: '不该被覆盖', done: false, createdAt: '2024-01-01T00:00:00.000Z' }],
    });
    localStorage.setItem(KEY, readonlyRaw);
    await reload();
    const roBanner = $('error-banner');
    const roInput = $('new-todo');
    const roSubmit = $('new-todo-submit');
    await submit('强制提交应被拒绝');
    log(
      !roBanner.hidden && roBanner.textContent.includes('只读模式') && roInput.disabled && roSubmit.disabled
        && items().length === 0 && storedRaw() === readonlyRaw,
      '路径12 只读降级',
      `错误条「${roBanner.textContent}」/ 输入禁用=${roInput.disabled} / 提交禁用=${roSubmit.disabled} / 列表 ${items().length} 条 / 存储逐字节不变=${storedRaw() === readonlyRaw}`,
    );

    // 路径13 键盘与语义结构
    clearState();
    await reload();
    const form = doc().getElementById('new-todo-form');
    const submitBtn = $('new-todo-submit');
    const label = doc().querySelector('label[for="new-todo"]');
    const focusables = Array.from(
      doc().querySelectorAll('a[href], input:not([disabled]), button:not([disabled])'),
    ).map((node) => node.id || node.className);
    log(
      form !== null && submitBtn.type === 'submit' && label !== null
        && $('notice').getAttribute('aria-live') === 'polite'
        && $('error-banner').getAttribute('role') === 'alert',
      '路径13 键盘与语义结构',
      `form=${form !== null} / 提交按钮 type=${submitBtn.type} / label[for]=${label !== null} / notice aria-live=${$('notice').getAttribute('aria-live')} / 错误条 role=${$('error-banner').getAttribute('role')} / 可聚焦序列 ${focusables.join(' → ')}`,
    );

    // 路径14 窄屏 320px
    frame.width = '320';
    await reload();
    await submit('超长标题'.repeat(50));
    const narrowDoc = doc();
    const clientWidth = narrowDoc.documentElement.clientWidth;
    const scrollWidth = narrowDoc.documentElement.scrollWidth;
    log(
      scrollWidth <= clientWidth,
      '路径14 窄屏无横向溢出',
      `iframe 宽 320 / clientWidth=${clientWidth} / scrollWidth=${scrollWidth} / 列表 ${items().length} 条（含 200 码点长标题）`,
    );

    clearState();
  } catch (error) {
    log(false, '驱动异常中断', String(error && error.stack ? error.stack : error).slice(0, 400));
  }

  report.textContent = `${lines.join('\n')}\n\n合计：${passCount}/${passCount + failCount} 通过，${failCount} 失败`;
  document.title = `DEMO-DONE ${passCount}/${passCount + failCount}`;
})();
</script>
</body>
</html>

