<body>
<p id="seed-status">正在准备本地数据，随后跳转到 index.html…</p>
<script>
/**
 * 截图种子页（仅测试用：产品页面不引用它）。
 *
 * 用途：为 `tests/screenshots/*.png` 造出四种可截图状态——真实浏览器里先写入真实
 * `localStorage`，再 `location.replace` 到真实的 `index.html`，因此截图拍的是产品页本身，
 * 而不是这个种子页。产品代码（index.html / styles.css / src/*.js）不读取任何 query 参数，
 * 状态完全来自 localStorage，与真实用户场景一致。
 *
 * 用法：/tests/screenshot-seed.html?state=empty|ready|corrupt|readonly
 */
(function seed() {
  var params = new URLSearchParams(location.search);
  var state = params.get('state') || 'empty';
  var KEY = 'todo.spa.state';
  var status = document.getElementById('seed-status');

  try {
    localStorage.clear();
  } catch (error) {
    status.textContent = '无法访问 localStorage：' + error.message;
    return;
  }

  if (state === 'ready') {
    // 2 条待办，其中 1 条已完成（对应「含条目 + 1 条已完成」）
    localStorage.setItem(KEY, JSON.stringify({
      schemaVersion: 1,
      todos: [
        { id: 'seed-1', title: '买牛奶（已完成）', done: true, createdAt: '2024-01-01T09:00:00.000Z' },
        { id: 'seed-2', title: '写一份可核对的验收证据', done: false, createdAt: '2024-01-02T10:30:00.000Z' }
      ]
    }));
  } else if (state === 'corrupt') {
    // 截断的 JSON：触发 STORAGE_CORRUPT（备份 + 空列表 + 可见错误条）
    localStorage.setItem(KEY, '{"schemaVersion":1,"todos":[');
  } else if (state === 'readonly') {
    // 版本过新：触发 SCHEMA_TOO_NEW（只读降级，绝不覆盖用户数据）
    localStorage.setItem(KEY, JSON.stringify({
      schemaVersion: 999,
      todos: [{ id: 'seed-future', title: '由更新版本写入的数据', done: false, createdAt: '2025-01-01T00:00:00.000Z', futureField: true }]
    }));
  }

  location.replace('../index.html?shot=' + encodeURIComponent(state));
})();
</script>
</body>
</html>

