<body>
<h1>Todo E2E 驱动（真实浏览器 + 真实 DOM 事件）</h1>
<p>本页把 <code>../index.html</code> 载入 iframe（同源），用真实点击 / 提交事件跑验收路径，结果写入下方报告。</p>
<iframe id="app" title="被驱动的 Todo 应用"></iframe>
<pre id="report">RUNNING</pre>
<script type="module">
const STORAGE_KEY = 'todo.spa.state';
const results = [];

function assert(cond, message) {
  if (!cond) throw new Error(message);
}

function record(status, name, detail) {
  results.push({ status, name, detail: detail || '' });
}

function check(name, fn) {
  try {
    record('PASS', name, fn());
  } catch (err) {
    record('FAIL', name, err && err.message ? err.message : String(err));
  }
}

async function checkAsync(name, fn) {
  try {
    record('PASS', name, await fn());
  } catch (err) {
    record('FAIL', name, err && err.message ? err.message : String(err));
  }
}

const frame = document.getElementById('app');
let reloadSeq = 0;

function loadApp() {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('iframe 加载超时（5s）')), 5000);
    frame.addEventListener(
      'load',
      () => {
        clearTimeout(timer);
        resolve();
      },
      { once: true },
    );
    reloadSeq += 1;
    frame.src = `../index.html?e2e=${reloadSeq}`;
  });
}

const tick = (ms = 30) => new Promise((resolve) => setTimeout(resolve, ms));
const doc = () => frame.contentDocument;
const $ = (id) => doc().getElementById(id);
const win = () => frame.contentWindow;
const isVisible = (element) => Boolean(element) && !element.hidden && win().getComputedStyle(element).display !== 'none';
const items = () => Array.from($('todo-list').children);
const storedState = () => JSON.parse(win().localStorage.getItem(STORAGE_KEY) || 'null');

function clearStorage() {
  win().localStorage.clear();
}

function push(text) {
  const input = $('new-todo');
  input.value = text;
  $('new-todo-submit').click();
}

async function main() {
  // ---------- 0. 清空存储后首次加载：加载态 → 空态 ----------
  await loadApp();
  clearStorage();
  await loadApp();

  check('路径6 空态：无数据时显示空态、列表为空、面板 data-state=empty', () => {
    assert(isVisible($('empty-state')), '#empty-state 应可见');
    assert(!isVisible($('loading-state')), '#loading-state（加载态）应已收起');
    assert(items().length === 0, `列表应为空，实际 ${items().length} 条`);
    assert($('todo-panel').dataset.state === 'empty', `面板状态应为 empty，实际 ${$('todo-panel').dataset.state}`);
    return 'empty-state 可见 / panel=empty / 列表 0 条';
  });

  // ---------- 1. 新增 ----------
  await checkAsync('路径1a 新增：输入后点击「添加」→ 渲染条目 + 成功提示 + 写入 localStorage', async () => {
    const input = $('new-todo');
    input.value = '  真实浏览器新增  ';
    $('new-todo-submit').click();
    await tick();
    const list = items();
    assert(list.length === 1, `应有 1 条，实际 ${list.length}`);
    const title = list[0].querySelector('.todo-title').textContent;
    assert(title === '真实浏览器新增', `标题应去首尾空白，实际「${title}」`);
    assert($('notice').textContent.includes('已添加'), `应有成功提示，实际「${$('notice').textContent}」`);
    assert(input.value === '', '提交后输入框应清空');
    const state = storedState();
    assert(state && state.todos.length === 1, 'localStorage 应已写入 1 条');
    assert(state.todos[0].title === '真实浏览器新增', 'localStorage 标题应一致');
    assert($('todo-panel').dataset.state === 'ready', `面板状态应为 ready，实际 ${$('todo-panel').dataset.state}`);
    return 'list=1 / localStorage 1 条 / panel=ready';
  });

  // ---------- 2. 标记完成 ----------
  await checkAsync('路径1b 标记完成：点击勾选框 → data-done=true + 持久化 done=true', async () => {
    items()[0].querySelector('.todo-checkbox').click();
    await tick();
    const item = items()[0];
    assert(item.dataset.done === 'true', '条目应带 data-done="true"');
    assert(item.querySelector('.todo-checkbox').checked === true, '勾选框应为选中');
    assert($('notice').textContent.includes('已标记完成'), `应有完成提示，实际「${$('notice').textContent}」`);
    assert(storedState().todos[0].done === true, 'localStorage done 应为 true');
    assert($('list-summary').textContent.includes('已完成 1 条'), `摘要应统计完成数，实际「${$('list-summary').textContent}」`);
    return 'data-done=true / done=true / 摘要已更新';
  });

  // ---------- 3. 取消完成 ----------
  await checkAsync('路径1c 取消完成：再次点击勾选框 → data-done 移除 + 持久化 false', async () => {
    items()[0].querySelector('.todo-checkbox').click();
    await tick();
    const item = items()[0];
    assert(item.dataset.done === undefined, '条目不应再带 data-done');
    assert($('notice').textContent.includes('已取消完成'), `应取消完成提示，实际「${$('notice').textContent}」`);
    assert(storedState().todos[0].done === false, 'localStorage done 应为 false');
    return 'data-done 已移除 / done=false';
  });

  // ---------- 4. 删除 ----------
  await checkAsync('路径1d 删除：点击「删除」→ 条目移除 + 回空态 + 持久化同步', async () => {
    items()[0].querySelector('.todo-remove').click();
    await tick();
    assert(items().length === 0, `应删除至 0 条，实际 ${items().length}`);
    assert($('notice').textContent.includes('已删除'), `应有删除提示，实际「${$('notice').textContent}」`);
    assert(isVisible($('empty-state')), '删除最后一条后应显示空态');
    assert(storedState().todos.length === 0, 'localStorage 应为 0 条');
    return 'list=0 / empty-state 可见 / 持久化 0 条';
  });

  // ---------- 5. 刷新后由 localStorage 恢复 ----------
  await checkAsync('路径1e 刷新恢复：新增 2 条 + 标记完成 1 条后重载页面 → 列表与完成态一致', async () => {
    push('甲');
    await tick();
    push('乙');
    await tick();
    items()[1].querySelector('.todo-checkbox').click();
    await tick();
    const before = items().map((li) => [li.querySelector('.todo-title').textContent, li.dataset.done === 'true']);
    await loadApp(); // 真实页面重载（iframe 重新加载 index.html）
    const after = items().map((li) => [li.querySelector('.todo-title').textContent, li.dataset.done === 'true']);
    const expected = JSON.stringify([['甲', false], ['乙', true]]);
    assert(JSON.stringify(before) === expected, `重载前应为 ${expected}，实际 ${JSON.stringify(before)}`);
    assert(JSON.stringify(after) === expected, `重载后应为 ${expected}，实际 ${JSON.stringify(after)}`);
    return '重载前/后均为 [["甲",false],["乙",true]]';
  });

  // ---------- 6. 非法输入：空标题 ----------
  await checkAsync('路径2a 空标题：纯空白提交 → 可见提示 + aria-invalid + 不入库', async () => {
    const before = items().length;
    const persistenceBefore = win().localStorage.getItem(STORAGE_KEY);
    const input = $('new-todo');
    input.value = '   \u3000 ';
    $('new-todo-submit').click();
    await tick();
    assert(items().length === before, `列表不应变化，实际 ${items().length}（原 ${before}）`);
    const noticeText = $('notice').textContent;
    assert(noticeText.includes('标题不能为空'), `提示应说明空标题，实际「${noticeText}」`);
