    assert(items().length === 1, `requestSubmit 后应有 1 条，实际 ${items().length}`);
    assert(input.value === '', '提交后输入框应清空（焦点回到输入框）');

    const reachable = Array.from(doc().querySelectorAll('a[href], button, input')).map(
      (node) => node.id || node.className || node.tagName,
    );
    assert(reachable.includes('new-todo') && reachable.includes('new-todo-submit'), '输入框与提交按钮应在可聚焦序列中');
    assert(reachable.some((name) => String(name).includes('todo-checkbox')), '条目勾选框应在可聚焦序列中');
    assert(reachable.some((name) => String(name).includes('todo-remove')), '删除按钮应在可聚焦序列中');
    return `requestSubmit 生效 / 可聚焦序列：${reachable.join(' → ')}`;
  });

