    // 仅编译（不调用）：能捕获语法错误，不会执行任何副作用
    new Function(code);
    console.log(`OK    block#${index + 1}  ${code.length} 字符`);
  } catch (error) {
    failed += 1;
    console.log(`ERROR block#${index + 1}  ${code.length} 字符  —— ${error.message}`);
  }
});

console.log(`\n结论：${blocks.length} 个内联脚本块，${failed} 个有语法错误`);
process.exit(failed === 0 ? 0 : 1);
